        Spec: spec,
        UP: scope,
        LAST_CHILD_SCOPE: scope.new_child({}),
        CHILD_ERRORS: [],
        MODE: AUTO,
        MIN_MODE: AUTO,
        ROOT: target,
    })
    scope.maps[0][LAST_CHILD_SCOPE] = scope
    try:
